<template>
  <div style="background-color: white;">
    <div id="container"></div>
  </div>
</template>

<script setup>
import G6 from '@antv/g6';
import {getUrl} from '../api/getMsdvBackendURL.ts'

const url = getUrl() + '/antipatternType/list';
fetch(url)
    .then((res) => res.json())
    .then((data) => {
      // console.log(data)
      const typeList = data.data;

      //region 数据整形 data → formatData
      let formatData = {
        id: "Microservice Antipattern Type",
        children: [],
      }
      let parentList = []
      // 获取粗分类
      typeList.forEach(item => {
        if (!item.parentName) {
          parentList.push(item.name);

        }
      })
      // console.log(parentList);
      parentList.forEach(item => {
        let tmp = {
          id: item,
          children: []
        }
        formatData.children.push(tmp);
      })
      // console.log(formatData);
      formatData.children.forEach(item => {
        // console.log(item);
        typeList.forEach(elem => {
          if (elem.parentName === item.id) {
            let tmp = {
              id: elem.name
            }
            item.children.push(tmp)
          }
        })
      })
      // console.log(JSON.stringify(formatData));
      //endregion

      //region 渲染配置
      const container = document.getElementById('container');
      const width = container.scrollWidth;
      const height = container.scrollHeight || 800;
      const graph = new G6.TreeGraph({
        container: 'container',
        width,
        height,
        modes: {
          default: [
            {
              type: 'collapse-expand',
              onChange: function onChange(item, collapsed) {
                const data = item.getModel();
                data.collapsed = collapsed;
                return true;
              },
            },
            'drag-canvas',
            'zoom-canvas',
          ],
        },
        defaultNode: {
          size: 26,
          anchorPoints: [
            [0, 0.5],
            [1, 0.5],
          ],
        },
        defaultEdge: {
          type: 'cubic-horizontal',
        },
        layout: {
          type: 'compactBox',
          direction: 'LR',
          getId: function getId(d) {
            return d.id;
          },
          getHeight: function getHeight() {
            return 16;
          },
          getWidth: function getWidth() {
            return 16;
          },
          getVGap: function getVGap() {
            return 10;
          },
          getHGap: function getHGap() {
            return 100;
          },
        },
      });

      graph.node(function (node) {
        return {
          label: node.id,
          labelCfg: {
            offset: 10,
            position: node.children && node.children.length > 0 ? 'left' : 'right',
          },
        };
      });
      //endregion

      graph.data(formatData);
      graph.render();
      graph.fitView();

      if (typeof window !== 'undefined')
        window.onresize = () => {
          if (!graph || graph.get('destroyed')) return;
          if (!container || !container.scrollWidth || !container.scrollHeight) return;
          graph.changeSize(container.scrollWidth, container.scrollHeight);
        };
    });

</script>

